// ════════════════════════════════════════════════════════════════════════════
// Native oracles (independent of the slice/mirror code paths).
// ════════════════════════════════════════════════════════════════════════════

/// clean-kernel expr/meta.rs mix_hash — VERBATIM.
fn native_mix_hash(h: u64, k: u64) -> u64 {
    const M: u64 = 0xc6a4_a793_5bd1_e995;
    const R: u32 = 47;
    let mut k = k.wrapping_mul(M);
    k ^= k >> R;
    k ^= M;
    let mut h = h ^ k;
    h = h.wrapping_mul(M);
    h
}

/// clean-kernel murmur_hash_64a in the PRODUCTION block form (as-chunks ≡
/// chunks_exact(8) + remainder) — the modules carry the index-loop
/// transcription, so agreement proves [T-murmur-idx] on every tested name.
fn native_murmur_hash_64a(data: &[u8], seed: u64) -> u64 {
    const M: u64 = 0xc6a4_a793_5bd1_e995;
    const R: u32 = 47;
    let len = data.len();
    let mut h: u64 = seed ^ (len as u64).wrapping_mul(M);
    let mut chunks = data.chunks_exact(8);
    for block in &mut chunks {
        let mut k = u64::from_le_bytes(block.try_into().expect("8-byte chunk"));
        k = k.wrapping_mul(M);
        k ^= k >> (R & 63);
        k = k.wrapping_mul(M);
        h ^= k;
        h = h.wrapping_mul(M);
    }
    let tail = chunks.remainder();
    for (i, &b) in tail.iter().enumerate() {
        h ^= (b as u64) << (i.wrapping_mul(8) & 63);
    }
    if !tail.is_empty() {
        h = h.wrapping_mul(M);
    }
    h ^= h >> (R & 63);
    h = h.wrapping_mul(M);
    h ^= h >> (R & 63);
    h
}

/// A decoded Name component, leaf-to-root.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Comp {
    Str(Vec<u8>),
    Num(u64),
}

/// Native `from_string_uncached` with the REAL `split('.')` + REAL
/// `str::parse::<u64>()` (production name.rs:557-565): (leaf-to-root comps,
/// cached_hash). The modules carry the unrolled fold — agreement proves
/// [T-unroll] + [T-parse] on every name.
fn native_from_string_uncached(s: &str) -> (Vec<Comp>, u64) {
    let mut comps_root_to_leaf: Vec<Comp> = Vec::new();
    let mut h: u64 = 1723; // anon
    for part in s.split('.') {
        if let Ok(n) = part.parse::<u64>() {
            h = native_mix_hash(h, n);
            comps_root_to_leaf.push(Comp::Num(n));
        } else {
            h = native_mix_hash(h, native_murmur_hash_64a(part.as_bytes(), 11));
            comps_root_to_leaf.push(Comp::Str(part.as_bytes().to_vec()));
        }
    }
    let mut leaf_to_root = comps_root_to_leaf;
    leaf_to_root.reverse();
    (leaf_to_root, h)
}

// GOLDEN constants from the REAL clean-kernel binary (see module docs).
const GOLDEN_EVEN: u64 = 0xa4d1bd1a7cb52f69;
const GOLDEN_ODD: u64 = 0x354ebfa6972f4d9b;
const GOLDEN_EVEN_ZERO: u64 = 0x2076091997629979;
const GOLDEN_EVEN_SUCC_ODD: u64 = 0xec865926cd1ac83b;
const GOLDEN_ODD_SUCC_EVEN: u64 = 0x5ba0bd3737dc245b;
const GOLDEN_EVEN_REC: u64 = 0xf92e5777a3c24878;
const GOLDEN_ODD_REC: u64 = 0x5bc5e955c00e19b2;
const GOLDEN_TREE: u64 = 0x799c131f2f585927; // == round-4 pin
const GOLDEN_FOREST: u64 = 0x67467aab1408ef94; // == round-4 pin
const GOLDEN_TREE_NODE: u64 = 0x03b4a4808874f36c;
const GOLDEN_FOREST_NIL: u64 = 0x822a34902f0e630f;
const GOLDEN_FOREST_CONS: u64 = 0xd827f0f1c72b9057;
const GOLDEN_TREE_REC: u64 = 0x293412c406e2a88e; // == round-4 pin
const GOLDEN_FOREST_REC: u64 = 0x6d912edca1677fc9; // == round-4 pin
const GOLDEN_U: u64 = 0xae572a66f1f7b2e8;
const GOLDEN_V: u64 = 0x486e7075aebc6ca6;
const GOLDEN_ANON: u64 = 1723;

// ── the JIT-side raw Name decode ─────────────────────────────────────────────
// Offsets read VERBATIM off THIS emit (name_str_part / name_num_part bodies;
// identical to round 4): Name = 40 bytes { NameInner @0..32, cached_hash @32 };
// NameInner tag = i64 @0 (0=Anon, 1=Str, 2=Num); Str payload = { Arc<Name>
// @8, Arc<str> (ArcInner ptr @16, len @24) }; Num payload is FIELD-REORDERED:
// { n u64 @8, Arc<Name> @16 }. ArcInner repr: { strong @0, weak @8, data @16 }.

/// Walk a JIT-built Name at `ptr`: returns (leaf-to-root comps, root hash,
/// per-node hashes leaf-to-root). Panics on an unknown tag (fail-loud decode).
unsafe fn decode_jit_name(ptr: *const u8) -> (Vec<Comp>, u64, Vec<u64>) {
    unsafe {
        let mut comps = Vec::new();
        let mut node_hashes = Vec::new();
        let read_u64 = |p: *const u8| -> u64 { (p as *const u64).read_unaligned() };
        let read_ptr = |p: *const u8| -> *const u8 { (p as *const *const u8).read_unaligned() };
        let root_hash = read_u64(ptr.add(32));
        let mut cur = ptr;
        loop {
            let tag = read_u64(cur);
            node_hashes.push(read_u64(cur.add(32)));
            match tag {
                0 => break,
                1 => {
                    let parent_inner = read_ptr(cur.add(8));
                    let s_inner = read_ptr(cur.add(16));
                    let s_len = read_u64(cur.add(24)) as usize;
                    let bytes = std::slice::from_raw_parts(s_inner.add(16), s_len).to_vec();
                    comps.push(Comp::Str(bytes));
                    cur = parent_inner.add(16);
                }
                2 => {
                    let n = read_u64(cur.add(8));
                    let parent_inner = read_ptr(cur.add(16));
                    comps.push(Comp::Num(n));
                    cur = parent_inner.add(16);
                }
                t => panic!("decode_jit_name: unknown NameInner tag {t} (layout drift?)"),
            }
        }
        (comps, root_hash, node_hashes)
    }
}

/// Recompute the production hash chain from decoded comps (leaf-to-root):
/// per-node hashes leaf-to-root INCLUDING the final Anon node (1723).
fn recompute_hash_chain(comps: &[Comp]) -> Vec<u64> {
    let mut fwd = vec![1723u64];
    for c in comps.iter().rev() {
        let prev = *fwd.last().unwrap();
        let h = match c {
            Comp::Str(b) => native_mix_hash(prev, native_murmur_hash_64a(b, 11)),
            Comp::Num(n) => native_mix_hash(prev, *n),
        };
        fwd.push(h);
    }
    fwd.reverse();
    fwd
}

/// SAFE walk of a HOST-built (mirror) Name: (leaf-to-root comps, root hash).
fn native_name_comps(n: &rn::Name) -> (Vec<Comp>, u64) {
    let mut comps = Vec::new();
    let mut cur = n;
    loop {
        match &cur.inner {
            rn::NameInner::Anon => break,
            rn::NameInner::Str(p, s) => {
                comps.push(Comp::Str(s.as_bytes().to_vec()));
                cur = &**p;
            }
            rn::NameInner::Num(p, v) => {
                comps.push(Comp::Num(*v));
                cur = &**p;
            }
        }
    }
    (comps, n.cached_hash)
}

// ════════════════════════════════════════════════════════════════════════════
// The asymmetric deep comparator: native side walked SAFELY via mirror types
// (host-built memory), JIT side Names decoded RAW at the documented offsets
// with the per-node hash chain REVALIDATED on every comparison (fail-loud on
// any layout drift). Meta words compared bit-exact at every node.
// ════════════════════════════════════════════════════════════════════════════

/// Compare a native (host-built) Name against a JIT (module-built) Name.
fn name_eq_nj(native: &rn::Name, jit: &rn::Name) -> bool {
    let (ncomps, nhash) = native_name_comps(native);
    let (jcomps, jhash, jchain) = unsafe { decode_jit_name(jit as *const rn::Name as *const u8) };
    // Chain revalidation: the JIT name's per-node cached_hash values must be
    // the production recompute of its decoded comps — ALWAYS, not just when
    // the comparison is expected to succeed.
    let expect_chain = recompute_hash_chain(&jcomps);
    assert_eq!(
        jchain, expect_chain,
        "JIT Name per-node hash chain != production recompute (layout drift or hash bug?)"
    );
    ncomps == jcomps && nhash == jhash
}

fn level_eq_nj(native: &rn::Level, jit: &rn::Level) -> bool {
    match (native, jit) {
        (rn::Level::Zero, rn::Level::Zero) => true,
        (rn::Level::Succ(a), rn::Level::Succ(b)) => level_eq_nj(a, b),
        (rn::Level::Param(a), rn::Level::Param(b)) => name_eq_nj(a, b),
        _ => false,
    }
}

fn levels_eq_nj(native: &[rn::Level], jit: &[rn::Level]) -> bool {
    if native.len() != jit.len() {
        return false;
    }
    native
        .iter()
        .zip(jit.iter())
        .all(|(a, b)| level_eq_nj(a, b))
}

/// Deep native==JIT comparison: meta word bit-identical at EVERY node, then
/// structural (Let/Proj never occur on this path — any appearance fails).
fn deep_eq_nj(native: &rn::Expr, jit: &rn::Expr) -> bool {
    if native.meta.raw() != jit.meta.raw() {
        return false;
    }
    match (&native.kind, &jit.kind) {
        (rn::ExprKind::BVar(x), rn::ExprKind::BVar(y)) => x == y,
        (rn::ExprKind::FVar(x), rn::ExprKind::FVar(y)) => x == y,
        (rn::ExprKind::Sort(x), rn::ExprKind::Sort(y)) => level_eq_nj(x, y),
        (rn::ExprKind::Const(n1, l1), rn::ExprKind::Const(n2, l2)) => {
            name_eq_nj(n1, n2) && levels_eq_nj(l1, l2)
        }
        (rn::ExprKind::Lit(x), rn::ExprKind::Lit(y)) => x == y,
        (rn::ExprKind::App(f1, a1), rn::ExprKind::App(f2, a2)) => {
            deep_eq_nj(f1, f2) && deep_eq_nj(a1, a2)
        }
        (rn::ExprKind::Lam(b1, t1, y1), rn::ExprKind::Lam(b2, t2, y2)) => {
            b1 == b2 && deep_eq_nj(t1, t2) && deep_eq_nj(y1, y2)
        }
        (rn::ExprKind::Pi(b1, t1, y1), rn::ExprKind::Pi(b2, t2, y2)) => {
            b1 == b2 && deep_eq_nj(t1, t2) && deep_eq_nj(y1, y2)
        }
        _ => false,
    }
}

// ── JIT drivers ──────────────────────────────────────────────────────────────

type RnMainRootFn = extern "C" fn(*mut rn::Expr, u64, u64, u64);
type RnProbeRootFn = extern "C" fn(*mut [u64; 5], u64, u64);

fn jit_main_part(f: RnMainRootFn, family: u64, which: u64, sel: u64) -> rn::Expr {
    let mut slot = std::mem::MaybeUninit::<rn::Expr>::uninit();
    unsafe {
        f(slot.as_mut_ptr(), family, which, sel);
        slot.assume_init()
    }
}

fn native_main_part(family: u64, which: u64, sel: u64) -> rn::Expr {
    if family == 0 {
        let at = rn::family_even_odd();
        let lp = rn::family_even_odd_level_params();
        rn::build_mutual_recursor_part(&at, 0, &lp, which as usize, sel as usize)
    } else {
        let at = rn::family_tree_forest();
        let lp = rn::family_tree_forest_level_params();
        rn::build_mutual_recursor_part(&at, 1, &lp, which as usize, sel as usize)
    }
}

// Hand-built-name helpers for the ground truths (mirror machinery — the same
// fold production from_string performs).
fn hn1(s: &str) -> rn::Name {
    rn::fold_step(rn::name_anon(), s)
}
fn hn2(a: &str, b: &str) -> rn::Name {
    rn::fold_step(rn::fold_step(rn::name_anon(), a), b)
}

// App-spine head of an Expr (test-side walker for the IH-head checks).
fn spine_head(e: &rn::Expr) -> &rn::Expr {
    let mut cur = e;
    while let rn::ExprKind::App(f, _) = &cur.kind {
        cur = f;
    }
    cur
}

// Strip all leading lambdas.
fn strip_lams(e: &rn::Expr) -> &rn::Expr {
    let mut cur = e;
    while let rn::ExprKind::Lam(_, _, body) = &cur.kind {
        cur = body;
    }
    cur
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 1 — module sanity: both fixtures parse + validate 0; the full engine
// AND the full real-Name machinery are genuinely IN-MODULE (real bodies); the
// u32-model's interning table is GONE from the module text (the de-modeling
// is structural, not cosmetic).
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn rn_module_sanity_and_inmodule_surface() {
    for (text, what) in [
        (RN_MAIN_TRUST_IR, "build_mutual_rec_realnames_root closure"),
        (RN_PROBE_TRUST_IR, "realnames_name_probe_root closure"),
    ] {
        let module = parse_and_validate(text, what);
        let bodied = |sym: &str| {
            module
                .functions
                .iter()
                .find(|f| f.name == sym)
                .map(|f| !f.blocks.is_empty())
                .unwrap_or(false)
        };
        // The real-Name machinery must be in-module in BOTH fixtures.
        for sym in [
            "name_anon",
            "name_str_part",
            "name_num_part",
            "murmur_hash_64a_idx",
            "mix_hash",
            "parse_u64_ascii",
            "fold_step",
            "str_bytes_eq",
            "name_eq",
            "name_append_rec",
            "fresh_univ_name",
            "family_even_odd",
            "family_tree_forest",
        ] {
            assert!(
                bodied(sym),
                "`{sym}` must be IN-MODULE (real body) in {what}"
            );
        }
        // The de-modeled table must be GONE.
        assert!(
            !text.contains("rec_name_of") && !text.contains("RecPair"),
            "{what}: the u32-model interning table must NOT appear in the module"
        );
        assert!(
            text.contains("heap_alloc rust_heap"),
            "{what}: Arc::new children must lower to heap_alloc (not stubbed)"
        );
        assert!(
            text.contains("14313749767032793493"),
            "{what}: the mix_hash/murmur MurmurHash constant must be lowered"
        );
    }
    // The full mutual engine must be in-module in the MAIN fixture.
    let module = parse_and_validate(RN_MAIN_TRUST_IR, "main fixture");
    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    for sym in [
        "build_mutual_rec_realnames_root",
        "build_mutual_recursor_part",
        "build_recursor_type",
        "build_minor_premise_type",
        "build_recursor_rule_rhs",
        "compute_ctor_infos",
        "get_recursive_field_flags",
        "field_is_eliminably_recursive",
        "get_constructor_field_types",
        "get_constructor_return_indices",
        "name_in_set",
        "remap_residual_index_bvars",
        "remap_residual_index_bvars_for_minor",
        "ctor_motive_index",
        "field_motive_index",
        "Expr__from_kind",
        "ExprKind__compute_meta",
        "Expr__infer_implicit",
        "Expr__lift_at",
    ] {
        assert!(
            bodied(sym),
            "`{sym}` must be IN-MODULE (real body) in the main fixture"
        );
    }
    // Probe fixture: the probe root + picker.
    let module = parse_and_validate(RN_PROBE_TRUST_IR, "probe fixture");
    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    assert!(bodied("realnames_name_probe_root") && bodied("probe_pick"));
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 2 — the NAME PROBE: every name the family construction produces (ind
// names, ctor names in global minor order, the name_append_rec `.rec` names,
// fresh_univ_name's `u`, the level param `v`) is built by JIT MACHINE CODE and
// decodes BIT-IDENTICAL to the real clean-kernel goldens: root cached_hash ==
// golden, components == the native split+parse fold, per-node chain == the
// production recompute at EVERY node down to Anon(1723).
//
// ARMED-DEMO RECORD (2026-07-03, performed and observed): with
// GOLDEN_EVEN_REC deliberately corrupted to 0xf92e5777a3c24879 (+1), this
// test failed loudly:
//   assertion `left == right` failed: probe f0 i5 ("Even.rec"):
//     JIT cached_hash != clean-kernel golden
//     left: 17955384935732889720   (= 0xf92e5777a3c24878, the JIT value)
//    right: 17955384935732889721   (= the corrupted golden)
// — then the golden was restored and the test re-passed. The equalities are
// live, not vacuous.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn rn_name_probe_bitidentical_to_kernel_goldens() {
    type NameProbeResult = (u64, u64, Vec<Comp>, u64, Vec<u64>);

    let results = run_with_watchdog("name probe JIT sweep", move || {
        let buffer = jit_module(
            RN_PROBE_TRUST_IR,
            "realnames_name_probe_root",
            &rn_externs(),
        );
        let f: RnProbeRootFn =
            unsafe { std::mem::transmute(bind(&buffer, "realnames_name_probe_root")) };
        let mut out: Vec<NameProbeResult> = Vec::new();
        for family in 0u64..2 {
            let top = if family == 0 { 8 } else { 9 };
            for idx in 0..top {
                let mut slot = std::mem::MaybeUninit::<[u64; 5]>::zeroed();
                f(slot.as_mut_ptr(), family, idx);
                let (comps, hash, chain) = unsafe { decode_jit_name(slot.as_ptr() as *const u8) };
                out.push((family, idx, comps, hash, chain));
            }
        }
        out
    });

    let expect: [(u64, u64, &str, u64); 17] = [
        (0, 0, "Even", GOLDEN_EVEN),
        (0, 1, "Odd", GOLDEN_ODD),
        (0, 2, "Even.zero", GOLDEN_EVEN_ZERO),
        (0, 3, "Even.succ_odd", GOLDEN_EVEN_SUCC_ODD),
        (0, 4, "Odd.succ_even", GOLDEN_ODD_SUCC_EVEN),
        (0, 5, "Even.rec", GOLDEN_EVEN_REC),
        (0, 6, "Odd.rec", GOLDEN_ODD_REC),
        (0, 7, "u", GOLDEN_U),
        (1, 0, "Tree", GOLDEN_TREE),
        (1, 1, "Forest", GOLDEN_FOREST),
        (1, 2, "Tree.node", GOLDEN_TREE_NODE),
        (1, 3, "Forest.nil", GOLDEN_FOREST_NIL),
        (1, 4, "Forest.cons", GOLDEN_FOREST_CONS),
        (1, 5, "Tree.rec", GOLDEN_TREE_REC),
        (1, 6, "Forest.rec", GOLDEN_FOREST_REC),
        (1, 7, "u", GOLDEN_U),
        (1, 8, "v", GOLDEN_V),
    ];
    assert_eq!(results.len(), expect.len());
    for ((family, idx, comps, hash, chain), (ef, ei, dotted, golden)) in
        results.iter().zip(expect.iter())
    {
        assert_eq!((family, idx), (ef, ei));
        let (native_comps, native_hash) = native_from_string_uncached(dotted);
        assert_eq!(
            *hash, *golden,
            "probe f{family} i{idx} ({dotted:?}): JIT cached_hash != clean-kernel golden"
        );
        assert_eq!(
            *hash, native_hash,
            "probe f{family} i{idx} ({dotted:?}): JIT cached_hash != native production fold"
        );
        assert_eq!(
            comps, &native_comps,
            "probe f{family} i{idx} ({dotted:?}): decoded components != native split fold"
        );
        let expect_chain = recompute_hash_chain(comps);
        assert_eq!(
            chain, &expect_chain,
            "probe f{family} i{idx} ({dotted:?}): per-node cached_hash chain != production recompute"
        );
        assert_eq!(
            *chain.last().unwrap(),
            GOLDEN_ANON,
            "every chain must terminate at the production Anon hash (1723)"
        );
        // Native mirror agreement (the same probe computed host-side).
        let native_name = if *family == 0 {
            rn::probe_pick(
                &rn::family_even_odd(),
                &rn::family_even_odd_level_params(),
                *idx,
            )
        } else {
            rn::probe_pick(
                &rn::family_tree_forest(),
                &rn::family_tree_forest_level_params(),
                *idx,
            )
        };
        let (mcomps, mhash) = native_name_comps(&native_name);
        assert_eq!(*hash, mhash, "probe f{family} i{idx}: JIT != mirror hash");
        assert_eq!(
            comps, &mcomps,
            "probe f{family} i{idx}: JIT != mirror comps"
        );
    }

    // NEGATIVE CONTROLS (armed): corrupted golden and crossed names disagree —
    // the equalities above are sensitive to every bit.
    assert_ne!(
        results[5].3,
        GOLDEN_EVEN_REC.wrapping_add(1),
        "negative control must FAIL: golden+1 should disagree"
    );
    assert_ne!(
        results[5].3, results[6].3,
        "negative control must FAIL: Even.rec and Odd.rec must hash differently"
    );
    let (corrupt_comps, _) = native_from_string_uncached("EveX.rec");
    assert_ne!(
        &results[5].2, &corrupt_comps,
        "negative control must FAIL: corrupted component should disagree"
    );
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 3 — Even/Odd: native == JIT over every output of both recursors, PLUS
// the landed ground truths rebuilt with REAL names: GT1 (hand-built Lean-
// documented Even.rec TYPE) and GT2 (hand-built Odd.rec rule[succ_even] RHS —
// the cross-recursor IH names Even.rec), and the wrong-recursor / wrong-minor
// negative controls.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn rn_even_odd_native_eq_jit_with_ground_truths() {
    let jit_outputs = run_with_watchdog("Even/Odd main JIT", move || {
        let buffer = jit_module(
            RN_MAIN_TRUST_IR,
            "build_mutual_rec_realnames_root",
            &rn_externs(),
        );
        let f: RnMainRootFn =
            unsafe { std::mem::transmute(bind(&buffer, "build_mutual_rec_realnames_root")) };
        let sels: [(u64, u64); 5] = [(0, 0), (0, 1), (0, 2), (1, 0), (1, 1)];
        let outs: Vec<rn::Expr> = sels
            .iter()
            .map(|&(which, sel)| jit_main_part(f, 0, which, sel))
            .collect();
        std::mem::forget(buffer); // keep machine-code-built Arcs immortal (leak model)
        outs
    });
    let labels = [
        "Even.rec TYPE",
        "Even.rec rule[zero]",
        "Even.rec rule[succ_odd]",
        "Odd.rec TYPE",
        "Odd.rec rule[succ_even]",
    ];
    let sels: [(u64, u64); 5] = [(0, 0), (0, 1), (0, 2), (1, 0), (1, 1)];
    for (i, &(which, sel)) in sels.iter().enumerate() {
        let native = native_main_part(0, which, sel);
        assert!(
            deep_eq_nj(&native, &jit_outputs[i]),
            "MUTUAL Even/Odd `{}`: JIT disagrees with native",
            labels[i]
        );
        assert_eq!(
            native.meta.raw(),
            jit_outputs[i].meta.raw(),
            "meta word disagrees on `{}`",
            labels[i]
        );
    }

    // ── GROUND TRUTH 1: hand-built Even.rec TYPE (Lean-documented shape),
    //    de-Bruijn-lowered independently of ALL builder code — REAL names. ──
    let d = rn::bi_default();
    let imp = rn::bi_implicit();
    let u = rn::Level::Param(hn1("u"));
    let even = rn::Expr::const_(hn1("Even"), vec![]);
    let odd = rn::Expr::const_(hn1("Odd"), vec![]);
    let zero = rn::Expr::const_(hn2("Even", "zero"), vec![]);
    let succ_odd = rn::Expr::const_(hn2("Even", "succ_odd"), vec![]);
    let succ_even = rn::Expr::const_(hn2("Odd", "succ_even"), vec![]);
    let m1_ty = rn::Expr::pi(d, even.clone(), rn::Expr::sort(u.clone()));
    let m2_ty = rn::Expr::pi(d, odd.clone(), rn::Expr::sort(u.clone()));
    // minor domains AS THEY APPEAR in the rec telescope (post per-minor lift):
    let n0_ty = rn::Expr::app(rn::Expr::bvar(1), zero.clone());
    let n1_ty = rn::Expr::pi(
        d,
        odd.clone(),
        rn::Expr::pi(
            d,
            rn::Expr::app(rn::Expr::bvar(2), rn::Expr::bvar(0)),
            rn::Expr::app(
                rn::Expr::bvar(4),
                rn::Expr::app(succ_odd.clone(), rn::Expr::bvar(1)),
            ),
        ),
    );
    let n2_ty = rn::Expr::pi(
        d,
        even.clone(),
        rn::Expr::pi(
            d,
            rn::Expr::app(rn::Expr::bvar(4), rn::Expr::bvar(0)),
            rn::Expr::app(
                rn::Expr::bvar(4),
                rn::Expr::app(succ_even.clone(), rn::Expr::bvar(1)),
            ),
        ),
    );
    let expected_even_rec_ty = rn::Expr::pi(
        imp,
        m1_ty.clone(),
        rn::Expr::pi(
            imp,
            m2_ty.clone(),
            rn::Expr::pi(
                d,
                n0_ty.clone(),
                rn::Expr::pi(
                    d,
                    n1_ty.clone(),
                    rn::Expr::pi(
                        d,
                        n2_ty.clone(),
                        rn::Expr::pi(
                            d,
                            even.clone(),
                            rn::Expr::app(rn::Expr::bvar(5), rn::Expr::bvar(0)),
                        ),
                    ),
                ),
            ),
        ),
    );
    assert!(
        deep_eq_nj(&expected_even_rec_ty, &jit_outputs[0]),
        "GROUND TRUTH: JIT Even.rec TYPE != hand-built Lean-documented shape"
    );

    // ── GROUND TRUTH 2: hand-built Odd.rec rule[succ_even] iota RHS — the
    //    CROSS-RECURSOR IH is Even.rec@{u} (built by name_append_rec IN THE
    //    MODULE; hand-built here by the same fold from_string performs):
    //      \ m1 m2 n0 n1 n2 (e : Even). n2 e (Even.rec@{u} m1 m2 n0 n1 n2 e)
    //    (minor selector = GLOBAL index 2 = minor_idx_offset(Even) + 0). ──
    let even_rec_c = rn::Expr::const_(hn2("Even", "rec"), vec![rn::Level::Param(hn1("u"))]);
    let ih = rn::Expr::app(
        rn::Expr::app(
            rn::Expr::app(
                rn::Expr::app(
                    rn::Expr::app(
                        rn::Expr::app(even_rec_c.clone(), rn::Expr::bvar(5)),
                        rn::Expr::bvar(4),
                    ),
                    rn::Expr::bvar(3),
                ),
                rn::Expr::bvar(2),
            ),
            rn::Expr::bvar(1),
        ),
        rn::Expr::bvar(0),
    );
    let body_correct = rn::Expr::app(
        rn::Expr::app(rn::Expr::bvar(1), rn::Expr::bvar(0)),
        ih.clone(),
    );
    let wrap_rhs = |body: rn::Expr| {
        rn::Expr::lam(
            d,
            m1_ty.clone(),
            rn::Expr::lam(
                d,
                m2_ty.clone(),
                rn::Expr::lam(
                    d,
                    n0_ty.clone(),
                    rn::Expr::lam(
                        d,
                        n1_ty.clone(),
                        rn::Expr::lam(d, n2_ty.clone(), rn::Expr::lam(d, even.clone(), body)),
                    ),
                ),
            ),
        )
    };
    let expected_odd_rule = wrap_rhs(body_correct);
    assert!(
        deep_eq_nj(&expected_odd_rule, &jit_outputs[4]),
        "GROUND TRUTH: JIT Odd.rec rule[succ_even] != hand-built iota RHS (cross-recursor IH)"
    );

    // ── NEGATIVE CONTROL A (fail-loud): an IH naming the WRONG recursor
    //    (Odd.rec instead of Even.rec) must NOT match the JIT output — if
    //    name_append_rec ever derived the wrong sibling, this catches it. ──
    let odd_rec_c = rn::Expr::const_(hn2("Odd", "rec"), vec![rn::Level::Param(hn1("u"))]);
    let ih_wrong = rn::Expr::app(
        rn::Expr::app(
            rn::Expr::app(
                rn::Expr::app(
                    rn::Expr::app(
                        rn::Expr::app(odd_rec_c, rn::Expr::bvar(5)),
                        rn::Expr::bvar(4),
                    ),
                    rn::Expr::bvar(3),
                ),
                rn::Expr::bvar(2),
            ),
            rn::Expr::bvar(1),
        ),
        rn::Expr::bvar(0),
    );
    let expected_wrong_ih = wrap_rhs(rn::Expr::app(
        rn::Expr::app(rn::Expr::bvar(1), rn::Expr::bvar(0)),
        ih_wrong,
    ));
    assert!(
        !deep_eq_nj(&expected_wrong_ih, &jit_outputs[4]),
        "NEGATIVE CONTROL: a wrong-recursor IH must NOT match the JIT output"
    );

    // ── NEGATIVE CONTROL B (fail-loud): the WRONG minor selector (local idx
    //    without minor_idx_offset: BVar(3) = n0 instead of BVar(1) = n2). ──
    let body_wrong_minor = rn::Expr::app(
        rn::Expr::app(rn::Expr::bvar(3), rn::Expr::bvar(0)),
        ih.clone(),
    );
    let expected_wrong_minor = wrap_rhs(body_wrong_minor);
    assert!(
        !deep_eq_nj(&expected_wrong_minor, &jit_outputs[4]),
        "NEGATIVE CONTROL: dropping minor_idx_offset must NOT match the JIT output"
    );
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 4 — Tree/Forest (parametric block): native == JIT over every output,
// GT3 (the Tree.rec rule[node] IH head must be the SIBLING recursor
// Forest.rec with levels [u, v]) with the head Name decoded RAW and matched
// BIT-IDENTICAL to the clean-kernel golden, and the crossed-head control.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn rn_tree_forest_native_eq_jit_with_ih_head() {
    let jit_outputs = run_with_watchdog("Tree/Forest main JIT", move || {
        let buffer = jit_module(
            RN_MAIN_TRUST_IR,
            "build_mutual_rec_realnames_root",
            &rn_externs(),
        );
        let f: RnMainRootFn =
            unsafe { std::mem::transmute(bind(&buffer, "build_mutual_rec_realnames_root")) };
        let sels: [(u64, u64); 5] = [(0, 0), (0, 1), (1, 0), (1, 1), (1, 2)];
        let outs: Vec<rn::Expr> = sels
            .iter()
            .map(|&(which, sel)| jit_main_part(f, 1, which, sel))
            .collect();
        std::mem::forget(buffer);
        outs
    });
    let labels = [
        "Tree.rec TYPE",
        "Tree.rec rule[node]",
        "Forest.rec TYPE",
        "Forest.rec rule[nil]",
        "Forest.rec rule[cons]",
    ];
    let sels: [(u64, u64); 5] = [(0, 0), (0, 1), (1, 0), (1, 1), (1, 2)];
    for (i, &(which, sel)) in sels.iter().enumerate() {
        let native = native_main_part(1, which, sel);
        assert!(
            deep_eq_nj(&native, &jit_outputs[i]),
            "MUTUAL Tree/Forest `{}`: JIT disagrees with native",
            labels[i]
        );
        assert_eq!(
            native.meta.raw(),
            jit_outputs[i].meta.raw(),
            "meta word disagrees on `{}`",
            labels[i]
        );
    }

    // ── GROUND TRUTH 3: in Tree.rec rule[node], the IH head must be the
    //    SIBLING recursor Forest.rec with levels [u, v]; the head Name is
    //    decoded RAW and matched against the clean-kernel golden. ──
    let jit_tree_node_rule = &jit_outputs[1];
    let body = strip_lams(jit_tree_node_rule);
    // body = App(App(App(minor, a), f_field), ih) — the LAST applied arg is the IH.
    let ih_arg = match &body.kind {
        rn::ExprKind::App(_, a) => a,
        other => panic!("Tree.node rule body is not an application: {other:?}"),
    };
    match &spine_head(ih_arg).kind {
        rn::ExprKind::Const(name, levels) => {
            let (comps, hash, chain) =
                unsafe { decode_jit_name(name as *const rn::Name as *const u8) };
            assert_eq!(
                chain,
                recompute_hash_chain(&comps),
                "IH head chain must revalidate"
            );
            assert_eq!(
                hash, GOLDEN_FOREST_REC,
                "MUTUAL IH must name the SIBLING recursor Forest.rec, bit-identical to the kernel"
            );
            let (expect_comps, _) = native_from_string_uncached("Forest.rec");
            assert_eq!(comps, expect_comps, "IH head components must be Forest.rec");
            // Levels must be [Param(u), Param(v)] — real Names, golden-checked.
            assert_eq!(levels.len(), 2, "IH recursor levels must be [u, v]");
            for (lv, golden) in levels.iter().zip([GOLDEN_U, GOLDEN_V]) {
                match lv {
                    rn::Level::Param(n) => {
                        let (lcomps, lhash, lchain) =
                            unsafe { decode_jit_name(n as *const rn::Name as *const u8) };
                        assert_eq!(lchain, recompute_hash_chain(&lcomps));
                        assert_eq!(lhash, golden, "IH level param golden mismatch");
                    }
                    other => panic!("IH level is not a Param: {other:?}"),
                }
            }
        }
        other => panic!("Tree.node IH head is not a Const: {other:?}"),
    }

    // ── NEGATIVE CONTROL (fail-loud): the crossed head — Tree.rec instead of
    //    the sibling Forest.rec — must NOT be what the module derived. ──
    match &spine_head(ih_arg).kind {
        rn::ExprKind::Const(name, _) => {
            let (_, hash, _) = unsafe { decode_jit_name(name as *const rn::Name as *const u8) };
            assert_ne!(
                hash, GOLDEN_TREE_REC,
                "NEGATIVE CONTROL: the IH head must not be the OWN recursor Tree.rec"
            );
        }
        _ => unreachable!(),
    }
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 5 — THE PRIZE: the `.rec` names INSIDE the verified rule RHSs (the
// cross-recursor IH heads of all three mutual rules) are constructed by the
// JIT machine code via the PRODUCTION derivation (name_append_rec over the
// REAL head Name pulled out of the field's return type) and decode
// BIT-IDENTICAL to the real clean-kernel goldens. The u32-model fixture
// asserted table-provided ids here; this asserts the real thing.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn rn_ih_rec_names_bitidentical_to_kernel() {
    let cases: Vec<(u64, u64, u64, &str, u64)> = vec![
        // (family, which, sel, expected IH-head dotted name, golden)
        (0, 1, 1, "Even.rec", GOLDEN_EVEN_REC), // Odd.rec rule[succ_even]: field Even
        (0, 0, 2, "Odd.rec", GOLDEN_ODD_REC),   // Even.rec rule[succ_odd]: field Odd
        (1, 0, 1, "Forest.rec", GOLDEN_FOREST_REC), // Tree.rec rule[node]: field Forest A
    ];
    let jit_rules = run_with_watchdog("IH-name main JIT", {
        let cases = cases.clone();
        move || {
            let buffer = jit_module(
                RN_MAIN_TRUST_IR,
                "build_mutual_rec_realnames_root",
                &rn_externs(),
            );
            let f: RnMainRootFn =
                unsafe { std::mem::transmute(bind(&buffer, "build_mutual_rec_realnames_root")) };
            let outs: Vec<rn::Expr> = cases
                .iter()
                .map(|&(family, which, sel, _, _)| jit_main_part(f, family, which, sel))
                .collect();
            std::mem::forget(buffer);
            outs
        }
    });
    for ((_, _, _, dotted, golden), rule) in cases.iter().zip(jit_rules.iter()) {
        let body = strip_lams(rule);
        let ih_arg = match &body.kind {
            rn::ExprKind::App(_, a) => a,
            other => panic!("rule body is not an application: {other:?}"),
        };
        match &spine_head(ih_arg).kind {
            rn::ExprKind::Const(name, _) => {
                let (comps, hash, chain) =
                    unsafe { decode_jit_name(name as *const rn::Name as *const u8) };
                assert_eq!(
                    chain,
                    recompute_hash_chain(&comps),
                    "IH chain must revalidate"
                );
                let (expect_comps, expect_hash) = native_from_string_uncached(dotted);
                assert_eq!(
                    hash, *golden,
                    "IH head for {dotted:?}: JIT cached_hash != clean-kernel golden"
                );
                assert_eq!(hash, expect_hash);
                assert_eq!(comps, expect_comps, "IH head comps for {dotted:?}");
            }
            other => panic!("IH head is not a Const: {other:?}"),
        }
    }
    // NEGATIVE CONTROL (armed): the three IH heads are pairwise distinct —
    // the derivation is head-sensitive, not constant.
    let h = |e: &rn::Expr| -> u64 {
        let body = strip_lams(e);
        let ih = match &body.kind {
            rn::ExprKind::App(_, a) => a,
            _ => unreachable!(),
        };
        match &spine_head(ih).kind {
            rn::ExprKind::Const(name, _) => unsafe {
                decode_jit_name(name as *const rn::Name as *const u8).1
            },
            _ => unreachable!(),
        }
    };
    assert_ne!(h(&jit_rules[0]), h(&jit_rules[1]));
    assert_ne!(h(&jit_rules[0]), h(&jit_rules[2]));
    assert_ne!(h(&jit_rules[1]), h(&jit_rules[2]));
}
